local function unhex(h)return(h:gsub("%x%x",function(cc)return string.char(tonumber(cc,16))end))end
local function clearlog()local f=io.open(LOG,"wb")if f then f:close()end end
local function readdev(off,n)sh("rm -f /tmp/r.bin");sh(string.format("dd if=%s of=/tmp/r.bin bs=1 skip=%d count=%d",DEV,off,n));local f=io.open("/tmp/r.bin","rb")if not f then return nil end local d=f:read("*a")f:close()return d end
local function wdev(off,s)local f=io.open("/tmp/w.bin","wb")if not f then return false end f:write(s)f:close()sh(string.format("dd if=/tmp/w.bin of=%s bs=1 seek=%d count=%d conv=notrunc",DEV,off,#s));return true end
local function szfield(e)local b=readdev(e.SZF,4)if not b or #b<4 then return nil end return b:byte(1)*16777216+b:byte(2)*65536+b:byte(3)*256+b:byte(4)end

local function inject(use_orig)
 clearlog()
 log(use_orig and "=== RESTORE 36 ICONS ===" or "=== INSTALL 36 ICONS ===")
 for _,e in ipairs(ENTRIES)do
  local h=readdev(e.DATA,24)
  if not h or #h<24 then log(e.name..": READ FAIL")return false,e.name.." read failed" end
  if h:byte(1)~=0x19 or (h:byte(2)~=0x08 and h:byte(2)~=0x0a) then log(e.name..": LVGL HEADER INVALID")return false,e.name.." header invalid" end
  local szf=szfield(e)
  if szf~=e.ORIG_SIZE then log(e.name..": SIZE GUARD FAIL")return false,e.name.." size guard failed" end
  local data=unhex(use_orig and e.ORIG_HEX or e.PAY_HEX)
  if #data~=e.SLOT then log(e.name..": SLOT FAIL")return false,e.name.." slot mismatch" end
  if data:byte(1)~=0x19 or (data:byte(2)~=0x08 and data:byte(2)~=0x0a) then log(e.name..": PAYLOAD INVALID")return false,e.name.." payload invalid" end
 end
 for i,e in ipairs(ENTRIES)do
  local data=unhex(use_orig and e.ORIG_HEX or e.PAY_HEX)
  if not wdev(e.DATA,data) then log(e.name..": WRITE FAIL")return false,e.name.." write failed" end
  local v=readdev(e.DATA,24)
  if not v or v~=data:sub(1,24) then log(e.name..": VERIFY FAIL")return false,e.name.." verify failed" end
  log(string.format("%02d/34 %s OK",i,e.name))
 end
 log(use_orig and "=== RESTORE COMPLETE ===" or "=== INSTALL COMPLETE ===")
 return true
end


local UI_W,UI_H=336,480
local uiRoot=SCRIPT_PATH or ""
local function uiFileExists(path)
 local f=io.open(path,"rb")
 if f then f:close()return true end
 return false
end
local uiIsS3=uiFileExists("/font/MiSans-Medium.ttf") or uiFileExists("/system/font/MiSans-Medium.ttf") or uiFileExists("/resource/font/MiSans-Medium.ttf")
local UI_FONT=lvgl.BUILTIN_FONT.MONTSERRAT_14
if uiIsS3 then UI_FONT=lvgl.Font("MiSans-Medium",32)else UI_FONT=lvgl.Font("misansw_Medium",32)end
local uiSuffix={}
local function uiImgPath(name)
 local path=uiRoot..name
 if uiSuffix[name] then return path..uiSuffix[name] end
 if uiFileExists(path..".bin") then uiSuffix[name]=".bin"return path..".bin" end
 if uiFileExists(path..".rle") then uiSuffix[name]=".rle"return path..".rle" end
 return path
end

local rootbase1=lvgl.Object(nil,{
 outline_width=0,border_width=0,pad_all=0,bg_opa=lvgl.OPA(100),
 bg_color=0,align=lvgl.ALIGN.CENTER,w=lvgl.HOR_RES(),h=lvgl.VER_RES()
})
rootbase1:clear_flag(lvgl.FLAG.SCROLLABLE)
rootbase1:add_flag(lvgl.FLAG.EVENT_BUBBLE)
local rootbase=lvgl.Object(rootbase1,{
 outline_width=0,border_width=0,pad_all=0,bg_opa=lvgl.OPA(100),
 bg_color=0,align=lvgl.ALIGN.CENTER,w=UI_W,h=UI_H
})
rootbase:clear_flag(lvgl.FLAG.SCROLLABLE)
rootbase:add_flag(lvgl.FLAG.EVENT_BUBBLE)

local uiPages={}
local function uiPage(name,asset,contentHeight,imgH)
 contentHeight=contentHeight or UI_H
 imgH=imgH or contentHeight
 local page=lvgl.Object(rootbase,{
  outline_width=0,border_width=0,pad_all=0,bg_opa=lvgl.OPA(100),
  bg_color=0,align=lvgl.ALIGN.CENTER,w=UI_W,h=UI_H
 })
 page:clear_flag(lvgl.FLAG.SCROLLABLE)
 page:add_flag(lvgl.FLAG.EVENT_BUBBLE)
 local content=lvgl.Object(page,{x=0,y=0,w=UI_W,h=UI_H,bg_opa=lvgl.OPA(0),border_width=0,pad_all=0})
 content:add_flag(lvgl.FLAG.EVENT_BUBBLE)
 if contentHeight<=UI_H then
  content:clear_flag(lvgl.FLAG.SCROLLABLE)
 else
  content:add_flag(lvgl.FLAG.SCROLLABLE)
  content:set {scroll_dir=lvgl.DIR.VER,scrollbar_mode=lvgl.SCROLLBAR_MODE.OFF}
 end
 local image=content:Image{src=uiImgPath(asset),x=0,y=0,w=UI_W,h=imgH}
 image:clear_flag(lvgl.FLAG.SCROLLABLE)
 image:clear_flag(lvgl.FLAG.CLICKABLE)
 uiPages[name]={page=page,content=content}
 return page,content
end
local function uiShow(target)
 for name,entry in pairs(uiPages)do
  if name==target then entry.page:clear_flag(lvgl.FLAG.HIDDEN)else entry.page:add_flag(lvgl.FLAG.HIDDEN)end
 end
end
local function uiHit(parent,x,y,w,h,callback)
 local obj=lvgl.Object(parent,{
  outline_width=0,border_width=0,pad_all=0,bg_opa=lvgl.OPA(0),
  x=x,y=y,w=w,h=h
 })
 obj:clear_flag(lvgl.FLAG.SCROLLABLE)
 obj:add_flag(lvgl.FLAG.CLICKABLE)
 obj:add_flag(lvgl.FLAG.EVENT_BUBBLE)
 obj:onevent(lvgl.EVENT.SHORT_CLICKED,function()callback()end)
 return obj
end

local mainPage=uiPage("index","index")
local helpPage,helpContent=uiPage("help","help",582)
local aboutPage,aboutContent=uiPage("about","about",480)
local installPage=uiPage("install","install_confirm")
local restorePage=uiPage("restore","restore_confirm")
local successPage,successContent=uiPage("success","install_success",560)
local logPage=uiPage("log","log",480,491)
local LOG_FONT=uiIsS3 and lvgl.Font("MiSans-Medium",20)or lvgl.Font("misansw_Medium",20)
local logText=logPage:Textarea{x=18,y=133,w=300,h=220,text="",text_color="#eeeeee",text_font=LOG_FONT,bg_color=0,bg_opa=lvgl.OPA(0),border_width=0,pad_all=8}
logText:add_flag(lvgl.FLAG.SCROLLABLE)
logText:add_flag(lvgl.FLAG.CLICKABLE)
logText:set {scroll_dir=lvgl.DIR.VER, scrollbar_mode=lvgl.SCROLLBAR_MODE.OFF}
local function refreshLog()
 logText:set{text=rl()}
end

local failurePage=lvgl.Object(rootbase,{
 outline_width=0,border_width=0,pad_all=0,bg_opa=lvgl.OPA(100),
 bg_color=0,align=lvgl.ALIGN.CENTER,w=UI_W,h=UI_H
})
failurePage:clear_flag(lvgl.FLAG.SCROLLABLE)
failurePage:add_flag(lvgl.FLAG.EVENT_BUBBLE)
local failureTitle=failurePage:Label{
 x=18,y=30,w=300,h=54,text="操作失败",text_color="#ffffff",
 text_font=UI_FONT,text_align=lvgl.ALIGN.TOP_MID
}
local failureText=failurePage:Label{
 x=18,y=112,w=300,h=250,text="请返回首页",text_color="#a8a8a8",
 text_font=UI_FONT,text_align=lvgl.ALIGN.TOP_MID
}
uiPages.failure={page=failurePage,content=failurePage}

local running=false
local function uiRun(useOrig)
 if running then return end
 running=true
 local ok,why=inject(useOrig)
 running=false
 if not ok then
  failureText:set{text="操作已中止\n"..tostring(why)}
  uiShow("failure")
  return
 end
 uiShow("success")
end

